  place.y = work->particles[63].y;
  Render_ApplyProjectedPlacementFar(work->objects[7], &place.x, &scale.x, 0);
  work->particles[63].x += work->particles[63].velocityX;
  work->particles[63].y += work->particles[63].velocityY;
