          s32 radius = (Random16() & 63) + 80;

          shard->x = target->x + ((Trig_Sin(angle) * radius) >> 1);
          shard->y = 0x80000;
          shard->z = (Trig_Cos(angle) * radius) >> 1;
          shard->velocityX = Random16();
          shard->velocityY = (Random16() & 0xffff) + 0x40000;
          shard->velocityZ = (Random16() & 7) + 4;
          shard->variant = -1;
