  hx = 200;
  hz = 0;
  REG_BG2PA = 0x80;
  REG_BG2X = 0;
  REG_BG2Y = -0x1000;
  REG_BLDALPHA = 0x1010;
  REG_BG2CNT = 0x784;
  REG_WININ = 0x2737;
  REG_WINOUT = 0x721;
  REG_WIN0V = 0x107c;
